sys_script_include.script:
var AggregationManagementUtils = Class.create();
AggregationManagementUtils.prototype = {
    initialize: function() {
    },

    newConnectionRequestAggregations: function(request) {
		var requestsysId = request.getValue('sys_id');
		var areaSysId = request.getValue('area');
		var request_type= request.getValue('request_type');
		var request_subtype =request.getValue('request_subtype');
		var description=request.getValue('description');
		var short_description=request.getValue('short_description');
		var aggregationSysId ='';
		//var requested_by=request.getValue('requested_by');

		var aggregation =new GlideRecord(
			'x_1966159_utilit_0_aggregations'
        );
		aggregation.addQuery('aggregation_type', 'new_connection');
        aggregation.addQuery('area', areaSysId);
        aggregation.addQuery('active', true);

        aggregation.query();
		if (aggregation.next()){
			aggregationSysId = aggregation.getValue('sys_id');
		}     
        else {
			aggregation.initialize();
			//aggregation.setValue('aggregation_type',request_type);
			aggregation.setValue('aggregation_type',request_type);
			aggregation.setValue('aggregation_request_subtype',request_subtype);
			aggregation.setValue('area',areaSysId);
			aggregationSysId = aggregation.insert();


        }
		//aggrgation member record creation 
		var aggregationMember =new GlideRecord('x_1966159_utilit_0_aggregation_members');
		aggregationMember.initialize();
		aggregationMember.setValue('aggregation', aggregationSysId);
		aggregationMember.setValue('new_connection_request',requestsysId);
		aggregationMember.insert();
	var updateAggregation = new GlideRecord(
		'x_1966159_utilit_0_aggregations'
		);
	updateAggregation.get(aggregationSysId);
	var totalRequests = parseInt(updateAggregation.getValue('total_requests'), 10);
	totalRequests = totalRequests + 1;
	updateAggregation.setValue('total_requests', totalRequests);
	updateAggregation.update();

    },

    type: 'AggregationManagementUtils'
}
;
